using VMLAssembler;

namespace VMLTranslators
{
    /// <summary>
    /// JVM 字节码翻译器
    /// 将 VML 汇编翻译为 JVM 字节码（.class 文件格式，输出 Jasmin 汇编语法）
    ///
    /// VML 寄存器映射策略：
    ///   R0-R7  → 局部变量槽 1-8（方法参数+局部变量）
    ///   R8-R15 → 局部变量槽 9-16
    ///   R12(BP) → 保留，不映射（JVM 有自己的栈帧）
    ///   R13(SP) → 保留，不映射（JVM 有自己的操作数栈）
    ///   R15(RA) → 保留，不映射（JVM 返回地址由 VM 管理）
    ///
    /// 浮点寄存器 F0-F15 → 局部变量槽 17-32
    ///
    /// VML 栈操作 → JVM 操作数栈
    /// VML 内存操作 → 静态 int[] memory 数组
    /// </summary>
    public class TranslatorJVM : TranslatorVM
    {
        public override string ARCH_NAME => "JVM";

        // JVM 无硬件中断支持 — 所有中断指令为 NOP
        protected override string[] ContextRegNames() => new string[0];
        protected override string NativeInt(int vector) => "";
        protected override string NativeIret() => "";
        protected override string NativeCli() => "";
        protected override string NativeSti() => "";
        protected override void EmitNativeInt(int vector) => Emit("    ; INT - JVM 无硬件中断");
        protected override void EmitNativeCli() => Emit("    ; CLI - JVM 无中断控制");
        protected override void EmitNativeSti() => Emit("    ; STI - JVM 无中断控制");

        // VML 寄存器 → JVM 局部变量槽映射
        private readonly Dictionary<int, int> REGISTER_MAP = new Dictionary<int, int>
        {
            { 0, 1 },   // R0 → slot 1
            { 1, 2 },   // R1 → slot 2
            { 2, 3 },   // R2 → slot 3
            { 3, 4 },   // R3 → slot 4
            { 4, 5 },   // R4 → slot 5
            { 5, 6 },   // R5 → slot 6
            { 6, 7 },   // R6 → slot 7
            { 7, 8 },   // R7 → slot 8
            { 8, 9 },   // R8 → slot 9
            { 9, 10 },  // R9 → slot 10
            { 10, 11 }, // R10 → slot 11
            { 11, 12 }, // R11 → slot 12
            // R12(BP), R13(SP), R14, R15(RA) 由 JVM 栈帧管理，不映射
        };

        // 浮点寄存器映射
        private readonly Dictionary<int, int> FLOAT_REGISTER_MAP = new Dictionary<int, int>
        {
            { 0, 17 }, { 1, 18 }, { 2, 19 }, { 3, 20 },
            { 4, 21 }, { 5, 22 }, { 6, 23 }, { 7, 24 },
            { 8, 25 }, { 9, 26 }, { 10, 27 }, { 11, 28 },
            { 12, 29 }, { 13, 30 }, { 14, 31 }, { 15, 32 }
        };

        // JVM 比较条件映射
        private readonly Dictionary<OpCode, string> CONDITION_MAP = new Dictionary<OpCode, string>
        {
            { OpCode.JE, "ifeq" },
            { OpCode.JNE, "ifne" },
            { OpCode.JZ, "ifeq" },
            { OpCode.JNZ, "ifne" },
            { OpCode.JL, "iflt" },
            { OpCode.JLE, "ifle" },
            { OpCode.JG, "ifgt" },
            { OpCode.JGE, "ifge" },
        };

        // 收集所有标签用于跳转指令
        private HashSet<string> definedLabels = new HashSet<string>();
        private int labelCounter = 0;

        public TranslatorJVM(VmlProgram vmlProgram) : base(vmlProgram)
        {
        }

        protected override void EmitHeader()
        {
            Emit("; JVM Bytecode (Jasmin syntax) - Translated from VML");
            Emit("; Generated by VML Translator");
            Emit("");
            Emit(".bytecode 49.0");
            Emit(".source vml_translated.java");
            Emit(".class public VMLProgram");
            Emit(".super java/lang/Object");
            Emit("");

            // 内存字段声明
            Emit("; === VML 内存模型（静态数组模拟）===");
            Emit(".field public static memory [I");
            Emit(".field public static memorySize I = 1048576");
            Emit(".field public static allocPtr I = 0");
            Emit("");

            // 默认构造函数
            Emit("; === 默认构造函数 ===");
            Emit(".method public <init>()V");
            Emit("    .limit stack 1");
            Emit("    .limit locals 1");
            Emit("    aload_0");
            Emit("    invokespecial java/lang/Object/<init>()V");
            Emit("    return");
            Emit(".end method");
            Emit("");

            // 内存初始化方法
            Emit("; === 内存初始化 ===");
            Emit(".method public static initMemory()V");
            Emit("    .limit stack 2");
            Emit("    .limit locals 0");
            Emit("    getstatic VMLProgram/memorySize I");
            Emit("    newarray int");
            Emit("    putstatic VMLProgram/memory [I");
            Emit("    return");
            Emit(".end method");
            Emit("");
        }

        protected override void EmitDataSection()
        {
            if (VmlProgram.DataSection.Count > 0)
            {
                Emit("; === 数据段初始化 ===");
                Emit(".method public static initData()V");
                Emit("    .limit stack 5");
                Emit("    .limit locals 2");
                Emit("");

                int addrCounter = 256; // 数据段从地址256开始

                foreach (var kvp in VmlProgram.DataSection)
                {
                    string name = kvp.Key;
                    object value = kvp.Value;

                    if (value is int intValue)
                    {
                        Emit($"    ; {name} = {intValue}");
                        Emit("    getstatic VMLProgram/memory [I");
                        Emit($"    ldc {addrCounter}");
                        Emit($"    ldc {intValue}");
                        Emit("    iastore");
                        LabelMap[name] = addrCounter.ToString();
                        addrCounter += 4;
                    }
                    else if (value is string strValue)
                    {
                        Emit($"    ; {name} = \"{strValue}\"");
                        byte[] bytes = System.Text.Encoding.UTF8.GetBytes(strValue);
                        for (int i = 0; i < bytes.Length; i++)
                        {
                            Emit("    getstatic VMLProgram/memory [I");
                            Emit($"    ldc {addrCounter + i}");
                            Emit($"    ldc {(int)bytes[i]}");
                            Emit("    iastore");
                        }
                        // NUL终止符
                        Emit("    getstatic VMLProgram/memory [I");
                        Emit($"    ldc {addrCounter + bytes.Length}");
                        Emit("    ldc 0");
                        Emit("    iastore");
                        LabelMap[name] = addrCounter.ToString();
                        addrCounter += bytes.Length + 1;
                    }
                    Emit("");
                }

                Emit("    return");
                Emit(".end method");
                Emit("");
            }
        }

        protected override void EmitCode()
        {
            // 收集所有标签
            CollectLabels();

            // 主方法
            Emit("; === 主程序 ===");
            Emit(".method public static main([Ljava/lang/String;)V");

            // 计算栈和局部变量需求
            int maxStack = 8;
            int maxLocals = 33; // 足够容纳所有寄存器映射 (R0-R14=15 + F0-F15=16 + 2 overhead)

            Emit($"    .limit stack {maxStack}");
            Emit($"    .limit locals {maxLocals}");
            Emit("");

            // 初始化内存
            Emit("    ; 初始化VML内存");
            Emit("    invokestatic VMLProgram/initMemory()V");

            // 初始化数据段
            if (VmlProgram.DataSection.Count > 0)
            {
                Emit("    invokestatic VMLProgram/initData()V");
            }

            // 设置栈指针 R13（在局部变量slot 13保存一个虚拟SP值）
            Emit("    ; 初始化栈指针");
            Emit("    getstatic VMLProgram/memorySize I");
            Emit("    ldc 4");
            Emit("    isub");
            Emit("    istore 13");
            Emit("");

            // 翻译每条指令
            foreach (var instr in VmlProgram.Instructions)
            {
                NormalizeAndTranslate(instr);
            }

            Emit("");
            Emit("    return");
            Emit(".end method");
        }

        protected override void EmitFooter()
        {
            // 为每个VML函数生成独立的Java方法
            // （当前版本：所有代码在main方法中，函数通过标签+跳转模拟）
            Emit("");
            Emit("; === VML Runtime Helper Methods ===");

            // memRead 方法
            Emit(".method public static memRead(I)I");
            Emit("    .limit stack 3");
            Emit("    .limit locals 1");
            Emit("    getstatic VMLProgram/memory [I");
            Emit("    iload_0");
            Emit("    iaload");
            Emit("    ireturn");
            Emit(".end method");
            Emit("");

            // memWrite 方法
            Emit(".method public static memWrite(II)V");
            Emit("    .limit stack 3");
            Emit("    .limit locals 2");
            Emit("    getstatic VMLProgram/memory [I");
            Emit("    iload_0");
            Emit("    iload_1");
            Emit("    iastore");
            Emit("    return");
            Emit(".end method");
            Emit("");

            // VML打印方法（用于SYSCALL #1等）
            Emit(".method public static vmlPrint(I)V");
            Emit("    .limit stack 2");
            Emit("    .limit locals 1");
            Emit("    getstatic java/lang/System/out Ljava/io/PrintStream;");
            Emit("    iload_0");
            Emit("    invokevirtual java/io/PrintStream/print(I)V");
            Emit("    return");
            Emit(".end method");
            Emit("");

            // VML打印字符串方法
            Emit(".method public static vmlPrintString(I)V");
            Emit("    .limit stack 4");
            Emit("    .limit locals 3");
            Emit("    new java/lang/StringBuilder");
            Emit("    dup");
            Emit("    invokespecial java/lang/StringBuilder/<init>()V");
            Emit("    iload_0");
            Emit("    invokestatic VMLProgram/readString(I)Ljava/lang/String;");
            Emit("    invokevirtual java/lang/StringBuilder/append(Ljava/lang/String;)Ljava/lang/StringBuilder;");
            Emit("    invokevirtual java/lang/StringBuilder/toString()Ljava/lang/String;");
            Emit("    getstatic java/lang/System/out Ljava/io/PrintStream;");
            Emit("    swap");
            Emit("    invokevirtual java/io/PrintStream/print(Ljava/lang/String;)V");
            Emit("    return");
            Emit(".end method");
            Emit("");

            // readString 方法
            Emit(".method public static readString(I)Ljava/lang/String;");
            Emit("    .limit stack 5");
            Emit("    .limit locals 3");
            Emit("    new java/lang/StringBuilder");
            Emit("    dup");
            Emit("    invokespecial java/lang/StringBuilder/<init>()V");
            Emit("    astore_1");
            Emit("    iload_0");
            Emit("    istore_2");
            Emit("loop_start:");
            Emit("    getstatic VMLProgram/memory [I");
            Emit("    iload_2");
            Emit("    iaload");
            Emit("    ifeq loop_end");
            Emit("    aload_1");
            Emit("    getstatic VMLProgram/memory [I");
            Emit("    iload_2");
            Emit("    iaload");
            Emit("    i2c");
            Emit("    invokevirtual java/lang/StringBuilder/append(C)Ljava/lang/StringBuilder;");
            Emit("    pop");
            Emit("    iinc 2 1");
            Emit("    goto loop_start");
            Emit("loop_end:");
            Emit("    aload_1");
            Emit("    invokevirtual java/lang/StringBuilder/toString()Ljava/lang/String;");
            Emit("    areturn");
            Emit(".end method");
            Emit("");
        }

        private void CollectLabels()
        {
            foreach (var instr in VmlProgram.Instructions)
            {
                if (instr.Opcode == OpCode.LABEL && instr.Operands.Count > 0)
                {
                    string labelName = instr.Operands[0].Value?.ToString() ?? "";
                    definedLabels.Add(labelName);
                }
            }
        }

        protected override void TranslateInstruction(Instruction instr)
        {
            // NormalizeBinaryOp handled by BaseTranslator.NormalizeAndTranslate
            switch (instr.Opcode)
            {
                // === 标签 ===
                case OpCode.LABEL:
                    {
                        string name = SanitizeLabel(instr.Operands[0].Value?.ToString() ?? "");
                        Emit($"{name}:");
                    }
                    break;

                // === 数据传输 ===
                                                case OpCode.MOVE:
                    TranslateMove(instr);
                    break;

                // === 栈操作 ===
                case OpCode.PUSH:
                    {
                        var src = instr.Operands[0];
                        LoadOperandToStack(src);
                        // JVM没有显式push，操作数栈自动管理
                        // 但VML的PUSH是压入调用栈，用局部变量槽模拟
                        // 简化：直接在操作数栈上保留值（调用者负责管理）
                    }
                    break;
                case OpCode.POP:
                    {
                        var dst = instr.Operands[0];
                        // 从操作数栈弹出到局部变量
                        StoreStackToLocal(dst);
                    }
                    break;

                // === 算术运算 ===
                case OpCode.ADD:
                    TranslateBinaryOp(instr, "iadd");
                    break;
                case OpCode.SUB:
                    TranslateBinaryOp(instr, "isub");
                    break;
                case OpCode.MUL:
                    TranslateBinaryOp(instr, "imul");
                    break;
                case OpCode.DIV:
                    TranslateBinaryOp(instr, "idiv");
                    break;
                case OpCode.MOD:
                    TranslateBinaryOp(instr, "irem");
                    break;
                case OpCode.INC:
                    {
                        var dst = instr.Operands[0];
                        int slot = GetLocalSlot(dst);
                        Emit($"    iinc {slot} 1");
                    }
                    break;
                case OpCode.DEC:
                    {
                        var dst = instr.Operands[0];
                        int slot = GetLocalSlot(dst);
                        Emit($"    iinc {slot} -1");
                    }
                    break;
                case OpCode.NEG:
                    {
                        var dst = instr.Operands[0];
                        LoadOperandToStack(dst);
                        Emit("    ineg");
                        StoreStackToLocal(dst);
                    }
                    break;

                // === 逻辑运算 ===
                case OpCode.AND:
                    TranslateBinaryOp(instr, "iand");
                    break;
                case OpCode.OR:
                    TranslateBinaryOp(instr, "ior");
                    break;
                case OpCode.XOR:
                    TranslateBinaryOp(instr, "ixor");
                    break;
                case OpCode.NOT:
                    {
                        var dst = instr.Operands[0];
                        LoadOperandToStack(dst);
                        Emit("    ldc -1");
                        Emit("    ixor");
                        StoreStackToLocal(dst);
                    }
                    break;
                case OpCode.SHL:
                    {
                        var dst = instr.Operands[0];
                        var src1 = instr.Operands[1];
                        var src2 = instr.Operands[2];
                        LoadOperandToStack(src1);
                        LoadOperandToStack(src2);
                        Emit("    ishl");
                        StoreStackToLocal(dst);
                    }
                    break;
                case OpCode.SHR:
                    {
                        var dst = instr.Operands[0];
                        var src1 = instr.Operands[1];
                        var src2 = instr.Operands[2];
                        LoadOperandToStack(src1);
                        LoadOperandToStack(src2);
                        Emit("    ishr");
                        StoreStackToLocal(dst);
                    }
                    break;

                // === 比较与跳转 ===
                case OpCode.CMP:
                    TranslateCmp(instr);
                    break;
                case OpCode.TEST:
                    {
                        var src1 = instr.Operands[0];
                        var src2 = instr.Operands[1];
                        LoadOperandToStack(src1);
                        LoadOperandToStack(src2);
                        Emit("    iand");
                        // 结果留在栈上，后续JZ/JNZ会消费
                    }
                    break;
                case OpCode.JMP:
                    {
                        string label = SanitizeLabel(instr.Operands[0].Value?.ToString() ?? "");
                        Emit($"    goto {label}");
                    }
                    break;
                case OpCode.JZ:
                case OpCode.JE:
                case OpCode.JNE:
                case OpCode.JNZ:
                    TranslateConditionalJump(instr);
                    break;
                case OpCode.JL:
                case OpCode.JLE:
                case OpCode.JG:
                case OpCode.JGE:
                    TranslateComparisonJump(instr);
                    break;

                // === 函数调用 ===
                case OpCode.CALL:
                    {
                        string target = SanitizeLabel(instr.Operands[0].Value?.ToString() ?? "");
                        // VML函数在当前版本是同一方法内的标签跳转
                        // 保存返回地址到R15（slot 15）
                        string returnLabel = $"ret_{labelCounter++}";
                        Emit($"    ldc \"{returnLabel}\"");
                        Emit("    astore 15");
                        Emit($"    goto {target}");
                        Emit($"    {returnLabel}:");
                    }
                    break;
                case OpCode.RET:
                    Emit("    aload 15");
                    // 简化：JVM不能动态跳转到字符串标签
                    // 使用switch或if-else链模拟
                    Emit("    ; RET: 跳转回调用点（由JVM方法返回模拟）");
                    Emit("    return");
                    break;
                // case OpCode.RET_VAL:
                //     {
                //         var src = instr.Operands[0];
                //         LoadOperandToStack(src);
                //         Emit("    istore 0"); // 返回值存slot 0
                //     }
                //     break;

                // === 系统调用 ===
                case OpCode.SYSCALL:
                    TranslateSyscall(instr);
                    break;
                case OpCode.HALT:
                    Emit("    return");
                    break;
                case OpCode.NOP:
                    Emit("    ; nop");
                    break;

                // === 浮点运算 ===
                case OpCode.FADD:
                    TranslateFloatBinaryOp(instr, "fadd");
                    break;
                case OpCode.FSUB:
                    TranslateFloatBinaryOp(instr, "fsub");
                    break;
                case OpCode.FMUL:
                    TranslateFloatBinaryOp(instr, "fmul");
                    break;
                case OpCode.FDIV:
                    TranslateFloatBinaryOp(instr, "fdiv");
                    break;
                case OpCode.FNEG:
                    {
                        var dst = instr.Operands[0];
                        LoadFloatToStack(dst);
                        Emit("    fneg");
                        StoreStackToFloatLocal(dst);
                    }
                    break;
                case OpCode.FCMP:
                    {
                        var src1 = instr.Operands[0];
                        var src2 = instr.Operands[1];
                        LoadFloatToStack(src1);
                        LoadFloatToStack(src2);
                        Emit("    fcmpl");
                        // 结果: -1/0/1 在栈上
                    }
                    break;

                // === 浮点转换 ===
                case OpCode.I2F:
                    {
                        var dst = instr.Operands[0];
                        var src = instr.Operands[1];
                        LoadOperandToStack(src);
                        Emit("    i2f");
                        StoreStackToFloatLocal(dst);
                    }
                    break;
                case OpCode.F2I:
                    {
                        var dst = instr.Operands[0];
                        var src = instr.Operands[1];
                        LoadFloatToStack(src);
                        Emit("    f2i");
                        StoreStackToLocal(dst);
                    }
                    break;
                case OpCode.MOVEF:
                                // MOVEF store path: dest != REGISTER → FSTORE (handled via goto from MOVEF above)
                                case OpCode.FPUSH:
                    LoadFloatToStack(instr.Operands[0]);
                    break;
                case OpCode.FPOP:
                    StoreStackToFloatLocal(instr.Operands[0]);
                    break;

                // === 栈帧管理 ===
                case OpCode.ENTER:
                    // JVM自动管理栈帧，忽略
                    Emit("    ; ENTER: JVM自动管理栈帧");
                    break;
                case OpCode.LEAVE:
                    Emit("    ; LEAVE: JVM自动管理栈帧");
                    break;

                // === 地址计算 ===
                                // === 标志位 ===
                case OpCode.CLC:
                case OpCode.STC:
                    Emit($"    ; {instr.Opcode}: 标志位操作在JVM中不适用");
                    break;

                                                                                case OpCode.MOVEB:
                    Emit("    i2b");
                    break;
                case OpCode.MOVEH:
                    Emit("    i2s");
                    break;
                case OpCode.PUSHB:
                case OpCode.PUSHH:
                    Emit("    ; PUSHB/PUSHW - value already on stack");
                    break;
                case OpCode.POPB:
                    Emit("    i2b");
                    Emit("    istore_3 ; POPB result");
                    break;
                case OpCode.POPH:
                    Emit("    i2s");
                    Emit("    istore_3 ; POPW result");
                    break;
                case OpCode.INT:
                case OpCode.IRET:
                // CLI/STI/INT/IRET handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.F2D:
                    Emit("    f2d");
                    break;
                case OpCode.D2F:
                    Emit("    d2f");
                    break;
                case OpCode.I2D:
                    Emit("    i2d");
                    break;
                case OpCode.D2I:
                    Emit("    d2i");
                    break;
                case OpCode.THROW:
                    Emit("    athrow");
                    break;
                case OpCode.CATCH:
                    Emit("    ; CATCH - exception handler start");
                    break;
                case OpCode.ENDCATCH:
                    Emit("    ; ENDCATCH - exception handler end");
                    break;
                case OpCode.SHLV:
                    Emit("    ishl");
                    break;
                case OpCode.SHRV:
                    Emit("    ishr");
                    break;
                case OpCode.ZERO:
                    Emit("    iconst_0");
                    break;

                // === 调试 ===
                case OpCode.BREAK:
                    Emit("    ; BREAK: 调试断点");
                    break;

                // === 内联汇编 ===
                // OpCode.ASM handled by BaseTranslator.TryTranslateCommonOpcode
                // OpCode.CHIPASM handled by BaseTranslator.TryTranslateCommonOpcode

                // 符号扩展 (JVM 原生) / 条件移动+循环移位 (软件库) (v1.66.28+)
                case OpCode.SEXTB: Emit("    i2b"); break;
                case OpCode.SEXTH: Emit("    i2s"); break;
                case OpCode.CMOVZ: case OpCode.CMOVNZ:
                case OpCode.ROL: case OpCode.ROR:
                    Emit($"    invokestatic VMLRuntime/__{instr.Opcode.ToString().ToLower()}()I");
                    break;

                default:
                    Emit($"    ; UNIMPLEMENTED: {instr.Opcode} {string.Join(", ", instr.Operands)}");
                    break;
            }
        }

        // === 辅助方法 ===

        private void TranslateLoad(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            if (src.Type == OperandType.IMMEDIATE)
            {
                int val = EvaluateExpression(src.Value?.ToString() ?? "0");
                if (val >= -1 && val <= 5)
                    Emit($"    iconst_{val}");
                else if (val >= -128 && val <= 127)
                    Emit($"    bipush {val}");
                else if (val >= -32768 && val <= 32767)
                    Emit($"    sipush {val}");
                else
                    Emit($"    ldc {val}");
                StoreStackToLocal(dst);
            }
            else if (src.Type == OperandType.REGISTER)
            {
                int srcSlot = GetLocalSlot(src);
                int dstSlot = GetLocalSlot(dst);
                if (srcSlot != dstSlot)
                {
                    Emit($"    iload {srcSlot}");
                    Emit($"    istore {dstSlot}");
                }
            }
            else if (src.Type == OperandType.MEMORY)
            {
                // memory[addr]
                string addr = ResolveAddress(src);
                Emit("    getstatic VMLProgram/memory [I");
                Emit($"    ldc {addr}");
                Emit("    iaload");
                StoreStackToLocal(dst);
            }
            else if (src.Type == OperandType.LABEL)
            {
                string labelName = src.Value?.ToString() ?? "";
                if (LabelMap.ContainsKey(labelName))
                {
                    Emit($"    ldc {LabelMap[labelName]}");
                }
                else
                {
                    Emit($"    ; LOAD label: {labelName} (地址待解析)");
                    Emit($"    ldc 0");
                }
                StoreStackToLocal(dst);
            }
        }

        private void TranslateStore(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            // memory[addr] = value
            string addr = ResolveAddress(dst);
            LoadOperandToStack(src);

            Emit("    getstatic VMLProgram/memory [I");
            Emit($"    ldc {addr}");
            Emit("    swap");  // swap value and index
            // 实际上需要：array, index, value → iastore
            // 当前栈：value, array, index → 需要调整
            // 重新组织
            Output.RemoveAt(Output.Count - 1); // remove swap
            Output.RemoveAt(Output.Count - 1); // remove ldc addr
            Output.RemoveAt(Output.Count - 1); // remove getstatic

            Emit("    getstatic VMLProgram/memory [I");
            Emit($"    ldc {addr}");
            LoadOperandToStack(src);
            Emit("    iastore");
        }

        private void TranslateMove(Instruction instr)
        {
            // v1.65.167+: 统一 MOVE — MEM/LABEL dest → Store, 其他 → Load
            if (instr.Operands[0].Type == OperandType.MEMORY ||
                instr.Operands[0].Type == OperandType.INDIRECT ||
                instr.Operands[0].Type == OperandType.LABEL)
            {
                TranslateStore(instr);
                return;
            }
            TranslateLoad(instr);
        }

        private void TranslateBinaryOp(Instruction instr, string jvmOp)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            LoadOperandToStack(src1);
            LoadOperandToStack(src2);
            Emit($"    {jvmOp}");
            StoreStackToLocal(dst);
        }

        private void TranslateFloatBinaryOp(Instruction instr, string jvmOp)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            LoadFloatToStack(src1);
            LoadFloatToStack(src2);
            Emit($"    {jvmOp}");
            StoreStackToFloatLocal(dst);
        }

        private void TranslateCmp(Instruction instr)
        {
            var src1 = instr.Operands[0];
            var src2 = instr.Operands[1];
            LoadOperandToStack(src1);
            LoadOperandToStack(src2);

            // 使用 isub 设置比较结果到操作数栈
            // 结果: <0 表示 src1 < src2, 0 表示相等, >0 表示 src1 > src2
            // 保存比较结果到 slot 14（虚拟比较结果寄存器）
            Emit("    isub");
            Emit("    istore 14");
        }

        private void TranslateConditionalJump(Instruction instr)
        {
            string label = SanitizeLabel(instr.Operands[0].Value?.ToString() ?? "");

            if (instr.Opcode == OpCode.JZ || instr.Opcode == OpCode.JE)
            {
                Emit("    iload 14");
                Emit($"    ifeq {label}");
            }
            else // JNZ, JNE
            {
                Emit("    iload 14");
                Emit($"    ifne {label}");
            }
        }

        private void TranslateComparisonJump(Instruction instr)
        {
            string label = SanitizeLabel(instr.Operands[0].Value?.ToString() ?? "");
            Emit("    iload 14");

            switch (instr.Opcode)
            {
                case OpCode.JL:
                    Emit($"    iflt {label}");
                    break;
                case OpCode.JLE:
                    Emit($"    ifle {label}");
                    break;
                case OpCode.JG:
                    Emit($"    ifgt {label}");
                    break;
                case OpCode.JGE:
                    Emit($"    ifge {label}");
                    break;
            }
        }

        private void TranslateSyscall(Instruction instr)
        {
            // SYSCALL #1 = print, #2 = print string
            if (instr.Operands.Count > 0 && instr.Operands[0].Type == OperandType.IMMEDIATE)
            {
                int syscallNum = Convert.ToInt32(instr.Operands[0].Value);
                switch (syscallNum)
                {
                    case 1: // print integer
                        Emit("    iload 0");  // R0
                        Emit("    invokestatic VMLProgram/vmlPrint(I)V");
                        break;
                    case 2: // print string
                        Emit("    iload 0");
                        Emit("    invokestatic VMLProgram/vmlPrintString(I)V");
                        break;
                    case 100: // read integer (简化)
                        Emit("    invokestatic java/lang/System/in Ljava/io/InputStream;");
                        Emit("    invokevirtual java/io/InputStream/read()I");
                        Emit("    istore 0");
                        break;
                    default:
                        Emit($"    ; SYSCALL #{syscallNum}: 未实现");
                        break;
                }
            }
        }

        // === 操作数加载/存储辅助 ===

        private void LoadOperandToStack(Operand operand)
        {
            switch (operand.Type)
            {
                case OperandType.IMMEDIATE:
                    int val = EvaluateExpression(operand.Value?.ToString() ?? "0");
                    if (val >= 0 && val <= 5)
                        Emit($"    iconst_{val}");
                    else if (val == -1)
                        Emit("    iconst_m1");
                    else if (val >= -128 && val <= 127)
                        Emit($"    bipush {val}");
                    else if (val >= -32768 && val <= 32767)
                        Emit($"    sipush {val}");
                    else
                        Emit($"    ldc {val}");
                    break;
                case OperandType.REGISTER:
                    int slot = GetLocalSlot(operand);
                    Emit($"    iload {slot}");
                    break;
                case OperandType.MEMORY:
                    string addr = ResolveAddress(operand);
                    Emit("    getstatic VMLProgram/memory [I");
                    Emit($"    ldc {addr}");
                    Emit("    iaload");
                    break;
                case OperandType.LABEL:
                    string labelName = operand.Value?.ToString() ?? "";
                    if (LabelMap.ContainsKey(labelName))
                        Emit($"    ldc {LabelMap[labelName]}");
                    else
                        Emit($"    ldc 0 ; unresolved: {labelName}");
                    break;
            }
        }

        private void StoreStackToLocal(Operand operand)
        {
            if (operand.Type == OperandType.REGISTER)
            {
                int slot = GetLocalSlot(operand);
                Emit($"    istore {slot}");
            }
            else if (operand.Type == OperandType.MEMORY)
            {
                string addr = ResolveAddress(operand);
                Emit("    getstatic VMLProgram/memory [I");
                Emit($"    ldc {addr}");
                Emit("    swap");
                Emit("    iastore");
            }
        }

        private void LoadFloatToStack(Operand operand)
        {
            if (operand.Type == OperandType.REGISTER)
            {
                // 检查是否是浮点寄存器（R0-R7映射到F0-F7时的约定）
                int regNum = Convert.ToInt32(operand.Value);
                if (FLOAT_REGISTER_MAP.ContainsKey(regNum))
                {
                    Emit($"    fload {FLOAT_REGISTER_MAP[regNum]}");
                }
                else
                {
                    // 从整数寄存器转换
                    Emit($"    iload {GetLocalSlot(operand)}");
                    // 需要位级转换 int→float
                    Emit("    invokestatic java/lang/Float/intBitsToFloat(I)F");
                }
            }
            else if (operand.Type == OperandType.IMMEDIATE)
            {
                Emit($"    ldc {operand.Value}f");
            }
        }

        private void StoreStackToFloatLocal(Operand operand)
        {
            if (operand.Type == OperandType.REGISTER)
            {
                int regNum = Convert.ToInt32(operand.Value);
                if (FLOAT_REGISTER_MAP.ContainsKey(regNum))
                {
                    Emit($"    fstore {FLOAT_REGISTER_MAP[regNum]}");
                }
                else
                {
                    // 转回整数存储
                    Emit("    invokestatic java/lang/Float/floatToRawIntBits(F)I");
                    Emit($"    istore {GetLocalSlot(operand)}");
                }
            }
        }

        private int GetLocalSlot(Operand operand)
        {
            if (operand.Type == OperandType.REGISTER)
            {
                int regNum = Convert.ToInt32(operand.Value);
                return REGISTER_MAP.TryGetValue(regNum, out int slot) ? slot : regNum + 1;
            }
            return 0;
        }

        private string ResolveAddress(Operand operand)
        {
            if (operand.Type == OperandType.MEMORY)
            {
                string val = operand.Value?.ToString() ?? "0";
                // 如果是 Rn 偏移格式
                if (val.StartsWith("R") || val.StartsWith("r"))
                {
                    string exprStr = val.Substring(1); // 去掉 'R' 前缀
                    int regNum = EvaluateExpression(exprStr);
                    int slot = GetLocalSlot(new Operand(OperandType.REGISTER, regNum));
                    return $"0 ; [R{regNum}] slot={slot} (runtime resolve needed)";
                }
                return val;
            }
            return operand.Value?.ToString() ?? "0";
        }

        // EvaluateExpression → uses BaseTranslator.EvaluateExpression

        // SanitizeLabel → uses TranslatorVM.SanitizeLabel

        protected override void EmitCall(Instruction instr)
            => Emit($"    invokestatic VMLRuntime/{instr.Opcode.ToString().ToLower()}()I");

        protected override string MapRegister(int regNum)
        {
            return REGISTER_MAP.TryGetValue(regNum, out int slot) ? $"slot_{slot}" : $"slot_{regNum + 1}";
        }
    }
}
